/**
 * 특정 날짜가 공휴일인지 확인하고 이름 반환
 * @param dateStr YYYY-MM-DD 형식의 날짜
 * @returns 공휴일 이름 또는 null
 */
export function getHolidayName(dateStr: string): string | null {
  const [yearStr, month, day] = dateStr.split('-');
  const year = parseInt(yearStr);
  const monthDay = `${month}-${day}`;
  
  // 고정 공휴일 체크
  if (FIXED_HOLIDAYS[monthDay]) {
    return FIXED_HOLIDAYS[monthDay];
  }
  
  // 음력 공휴일 체크
  const lunarHolidays = LUNAR_HOLIDAYS[year];
  if (lunarHolidays && lunarHolidays[monthDay]) {
    return lunarHolidays[monthDay];
  }
  
  return null;
}

/**
 * 특정 날짜가 공휴일인지 여부
 */
export function isHoliday(dateStr: string): boolean {
  return getHolidayName(dateStr) !== null;
}

/**
 * 특정 월의 모든 공휴일 목록 반환
 */
export function getMonthHolidays(year: number, month: number): Holiday[] {
  const holidays: Holiday[] = [];
  const monthStr = month.toString().padStart(2, '0');
  
  // 고정 공휴일
  Object.entries(FIXED_HOLIDAYS).forEach(([monthDay, name]) => {
    if (monthDay.startsWith(monthStr)) {
      holidays.push({
        name,
        date: `${year}-${monthDay}`,
      });
    }
  });
  
  // 음력 공휴일
  const lunarHolidays = LUNAR_HOLIDAYS[year];
  if (lunarHolidays) {
    Object.entries(lunarHolidays).forEach(([monthDay, name]) => {
      if (monthDay.startsWith(monthStr)) {
        holidays.push({
          name,
          date: `${year}-${monthDay}`,
        });
      }
    });
  }
  
  return holidays;
}
